import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[][] tasks = new long[n][2]; // (deadline, duration)
        for (int i = 0; i < n; i++) { tasks[i][1] = nextLong(); tasks[i][0] = nextLong(); }
        Arrays.sort(tasks, (x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0]) : Long.compare(x[1], y[1]));
        long time = 0;
        for (long[] t : tasks) {
            time += t[1];
            if (time > t[0]) { System.out.println(-1); return; }
        }
        System.out.println(time);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n := readInt()
	tasks := make([][2]int, n) // (deadline, duration)
	for i := range tasks {
		tasks[i][1] = readInt()
		tasks[i][0] = readInt()
	}
	sort.Slice(tasks, func(i, j int) bool {
		if tasks[i][0] != tasks[j][0] {
			return tasks[i][0] < tasks[j][0]
		}
		return tasks[i][1] < tasks[j][1]
	})
	time := 0
	for _, t := range tasks {
		time += t[1]
		if time > t[0] {
			fmt.Println(-1)
			return
		}
	}
	fmt.Println(time)
}
